mapper.select:
SELECT count(*) FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) JOIN BASIL_ODS_PRD.XREF_SHIP ship USING (BOX_OID) JOIN BASIL_ODS_PRD.XREF_FAULT_CODE xfc USING (xm_OID) JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE
mo.MC_OID = #{id}
AND mo.MO_OID = #{rmaNumber}
AND msn.SERIAL_NUMBER LIKE concat('%',#{serialNumber},'%')
AND part.PART_NUMBER_SHORT LIKE concat('%',#{partNumber},'%')
AND xm.STATUS = 113

SELECT ship.SHIP_DATE as shipDate, part.PART_NUMBER_SHORT as partNumber, msn.SERIAL_NUMBER as serialNumber, mo.MO_OID as rmaNumber, ship.TRACKING_NUMBER as trackingNumber, xm.CUSTOMER_REPORTED_ISSUE_EXT as reportedIssue, fault.VALUE as faultCode FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) JOIN BASIL_ODS_PRD.XREF_SHIP ship USING (BOX_OID) JOIN BASIL_ODS_PRD.XREF_FAULT_CODE xfc USING (xm_OID) JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE
mo.MC_OID = #{id}
AND mo.MO_OID = #{rmaNumber}
AND msn.SERIAL_NUMBER LIKE concat('%',#{serialNumber},'%')
AND part.PART_NUMBER_SHORT LIKE concat('%',#{partNumber},'%')
AND xm.STATUS = 113
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT count(*) FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) JOIN BASIL_ODS_PRD.XREF_FAULT_CODE xfc USING (xm_OID) JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE LEFT JOIN BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES sav ON sav.SAV_OID = xm.CUSTOMER_CONTACT_NEEDED
mo.MC_OID = #{id}
AND mo.MO_OID = #{rmaNumber}
AND msn.SERIAL_NUMBER LIKE concat('%',#{serialNumber},'%')
AND part.PART_NUMBER_SHORT LIKE concat('%',#{partNumber},'%')
AND xm.STATUS = 108

SELECT xm.QUARANTINE_DATE as quarantineDate, part.PART_NUMBER_SHORT as partNumber, msn.SERIAL_NUMBER as serialNumber, mo.MO_OID as rmaNumber, sav.VALUE as customerContact, xm.TECH_NOTES as techNotes, fault.VALUE AS faultCode FROM BASIL_ODS_PRD.MASTER_ORDER mo JOIN BASIL_ODS_PRD.XREF_MATERIALS xm USING (MO_OID) JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn USING (MSN_OID) JOIN BASIL_ODS_PRD.MASTER_PART part USING (PART_OID) JOIN BASIL_ODS_PRD.XREF_FAULT_CODE xfc USING (xm_OID) JOIN BASIL_ODS_PRD.SUPPORT_FAULT_CODE_VALUES fault ON fault.SFV_OID = xfc.FAULT_CODE LEFT JOIN BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES sav ON sav.SAV_OID = xm.CUSTOMER_CONTACT_NEEDED
mo.MC_OID = #{id}
AND mo.MO_OID = #{rmaNumber}
AND msn.SERIAL_NUMBER LIKE concat('%',#{serialNumber},'%')
AND part.PART_NUMBER_SHORT LIKE concat('%',#{partNumber},'%')
AND xm.STATUS = 108
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}
